SELECT COUNT(DISTINCT p.id) FROM posts p
-- 关联作者信息 LEFT JOIN "user" u ON p.author_id = u.id LEFT JOIN user_profiles up ON u.id = up.user_id
-- 关联分类信息 LEFT JOIN categories c ON p.category_id = c.id
-- 关联标签信息（可能导致重复） LEFT JOIN post_tags pt ON p.id = pt.post_id LEFT JOIN tags t ON pt.tag_id = t.id
-- 只获取已发布、允许公开访问且作者为活跃状态的文章 WHERE p.status = 'published' AND p.visibility = 'public' AND u.status = 'active'
-- 动态查询条件（与主查询保持一致） -- 关键字搜索
AND (p.title ILIKE CONCAT('%', #{params.q}, '%') OR p.excerpt ILIKE CONCAT('%', #{params.q}, '%') OR p.content ILIKE CONCAT('%', #{params.q}, '%') OR u.username ILIKE CONCAT('%', #{params.q}, '%') OR up.display_name ILIKE CONCAT('%', #{params.q}, '%'))
-- 分类ID过滤
AND p.category_id = #{params.categoryId}
-- 分类名称过滤
AND c.name = #{params.categoryName}
-- 标签ID过滤
AND EXISTS( SELECT 1 FROM post_tags pt2 WHERE pt2.post_id = p.id AND pt2.tag_id = #{params.tagId} )
-- 标签名称过滤
AND EXISTS( SELECT 1 FROM post_tags pt2 JOIN tags t2 ON pt2.tag_id = t2.id WHERE pt2.post_id = p.id AND t2.name = #{params.tagName} )
-- 作者ID过滤
AND p.author_id = #{params.authorId}
-- 作者用户名过滤
AND u.username = #{params.authorUsername}
-- 作者显示名称过滤
AND up.display_name = #{params.authorDisplayName}
-- 是否置顶过滤
AND p.is_top = #{params.isTop}
-- 是否精选过滤
AND p.is_featured = #{params.isFeatured}
-- 发布时间范围过滤
AND p.published_at >= #{params.pageable.startTime}
AND p.published_at <= #{params.pageable.endTime}

SELECT DISTINCT p.id, p.title, p.slug, p.cover_image_url AS coverImageUrl, p.view_count AS viewCount, p.published_at AS publishedAt, -- 计算相关度分数：相同分类+3分，共同标签每个+1分，浏览量权重 ( CASE WHEN p.category_id = #{categoryId} THEN 3 ELSE 0 END +
COALESCE(( SELECT COUNT(*) FROM post_tags pt1 WHERE pt1.post_id = p.id AND pt1.tag_id IN
#{tagId}
), 0) +
0 +
-- 浏览量权重（归一化到0-1分） LEAST(p.view_count * 0.001, 1) ) AS relevance_score FROM posts p LEFT JOIN "user" u ON p.author_id = u.id WHERE p.status = 'published' AND p.visibility = 'public' AND u.status = 'active' AND p.id != #{currentPostId}
AND (
-- 相同分类 p.category_id = #{categoryId}
OR
-- 有共同标签 EXISTS ( SELECT 1 FROM post_tags pt WHERE pt.post_id = p.id AND pt.tag_id IN
#{tagId}
)
)
ORDER BY relevance_score DESC, viewCount DESC, publishedAt DESC LIMIT #{limit}

SELECT DISTINCT -- 文章基本信息 p.id AS post_id, p.title AS post_title, p.slug AS post_slug, p.excerpt AS post_excerpt, p.cover_image_url AS post_cover_image_url, p.status AS post_status, p.visibility AS post_visibility, p.view_count AS post_view_count, p.like_count AS post_like_count, p.comment_count AS post_comment_count, p.share_count AS post_share_count, p.reading_time AS post_reading_time, p.word_count AS post_word_count, p.is_featured AS post_is_featured, p.is_top AS post_is_top, p.allow_comments AS post_allow_comments, p.created_at AS post_created_at, p.updated_at AS post_updated_at, p.published_at AS post_published_at, p.scheduled_at AS post_scheduled_at,
-- 作者信息 u.id AS author_id, u.username AS author_username, up.display_name AS author_display_name, up.avatar_url AS author_avatar_url, up.bio AS author_bio,
-- 分类信息 c.id AS category_id, c.name AS category_name, c.slug AS category_slug, c.description AS category_description,
-- 标签信息 t.id AS tag_id, t.name AS tag_name, t.slug AS tag_slug, t.color AS tag_color FROM posts p
-- 关联作者信息 LEFT JOIN "user" u ON p.author_id = u.id LEFT JOIN user_profiles up ON u.id = up.user_id
-- 关联分类信息 LEFT JOIN categories c ON p.category_id = c.id
-- 关联标签信息 LEFT JOIN post_tags pt ON p.id = pt.post_id LEFT JOIN tags t ON pt.tag_id = t.id
-- 只获取当前用户的文章 WHERE p.author_id = #{userId} AND u.status = 'active'
-- 动态查询条件
AND ( p.title ILIKE CONCAT('%', #{params.q}, '%') OR p.excerpt ILIKE CONCAT('%', #{params.q}, '%') OR p.content ILIKE CONCAT('%', #{params.q}, '%') )
AND p.status = #{params.status}
AND p.category_id = #{params.categoryId}
AND c.name ILIKE CONCAT('%', #{params.categoryName}, '%')
AND pt.tag_id = #{params.tagId}
AND t.name ILIKE CONCAT('%', #{params.tagName}, '%')
AND p.is_top = #{params.isTop}
AND p.is_featured = #{params.isFeatured}
AND p.visibility = #{params.visibility}
AND p.published_at >= #{params.pageable.startTime}
AND p.published_at <= #{params.pageable.endTime}
-- 动态排序 ORDER BY
p.created_at DESC p.created_at ASC p.updated_at DESC p.updated_at ASC p.published_at DESC p.published_at ASC p.title DESC p.title ASC p.view_count DESC p.view_count ASC p.updated_at DESC
p.updated_at DESC

