FROM posts p
INNER JOIN post_tags pt ON p.id = pt.post_id
WHERE p.status = #{params.status}
  AND p.visibility = #{params.visibility}
  AND pt.tag_id = #{tagId}

      AND p.is_featured = true

SELECT COUNT(DISTINCT p.id) FROM posts p LEFT JOIN "user" u ON p.author_id = u.id LEFT JOIN categories c ON p.category_id = c.id WHERE p.status = #{params.status} AND p.visibility = 'public' AND u.status = 'active'
AND p.category_id IN ( WITH RECURSIVE category_tree AS ( -- 基础查询：当前分类 SELECT id FROM categories WHERE id = #{categoryId} UNION ALL -- 递归查询：子分类 SELECT c.id FROM categories c INNER JOIN category_tree ct ON c.parent_id = ct.id ) SELECT id FROM category_tree )
AND p.category_id = #{categoryId}
